unsafe fn GetBestLengths(
    mut s: *mut ZopfliBlockState,
    mut in_0: *const c_uchar,
    mut instart: size_t,
    mut inend: size_t,
    mut costmodel: Option<CostModelFun>,
    mut costcontext: *mut c_void,
    mut length_array: *mut c_ushort,
    mut h: *mut ZopfliHash,
    mut costs: *mut c_float,
) -> c_double {
    let blocksize: size_t = inend.wrapping_sub(instart);
    let mut sublen: [c_ushort; 259] = [0; 259];
    let windowstart: size_t = if instart > ZOPFLI_WINDOW_SIZE as size_t {
        instart.wrapping_sub(ZOPFLI_WINDOW_SIZE as size_t)
    } else {
        0 as size_t
    };
    let mincost: c_double = GetCostModelMinCost(costmodel, costcontext);

    if instart == inend {
        return 0 as c_int as c_double;
    }

    let costfn = costmodel.expect("non-null function pointer");

    ZopfliResetHash(ZOPFLI_WINDOW_SIZE as size_t, h);
    ZopfliWarmupHash(in_0, windowstart, inend, h);

    let mut i = windowstart;
    while i < instart {
        ZopfliUpdateHash(in_0, i, inend, h);
        i = i.wrapping_add(1);
    }

    i = 1 as size_t;
    while i < blocksize.wrapping_add(1) {
        // SAFETY: caller provides costs with at least blocksize + 1 elements; i is in 1..=blocksize here.
        unsafe { *costs.add(i) = ZOPFLI_LARGE_FLOAT as c_float; }
        i = i.wrapping_add(1);
    }
    // SAFETY: caller provides costs and length_array with at least 1 element.
    unsafe {
        *costs.add(0) = 0 as c_int as c_float;
        *length_array.add(0) = 0 as c_ushort;
    }

    let h_same = (*h).same;
    let window_mask = ZOPFLI_WINDOW_MASK as size_t;
    let max_match_usize = ZOPFLI_MAX_MATCH as size_t;
    let max_match_ushort = ZOPFLI_MAX_MATCH as c_ushort;

    i = instart;
    while i < inend {
        let mut j: size_t = i.wrapping_sub(instart);
        ZopfliUpdateHash(in_0, i, inend, h);

        // SAFETY: h_same points to the same ring buffer used by the original code; masked indices stay in range.
        let same_i = unsafe { *h_same.add(i & window_mask) as c_int };
        if same_i > ZOPFLI_MAX_MATCH * 2 as c_int
            && i > instart.wrapping_add(max_match_usize).wrapping_add(1)
            && i.wrapping_add((ZOPFLI_MAX_MATCH * 2 as c_int) as size_t)
                .wrapping_add(1)
                < inend
            // SAFETY: same as above; masked index stays in range.
            && unsafe {
                *h_same.add(i.wrapping_sub(max_match_usize) & window_mask) as c_int
            } > ZOPFLI_MAX_MATCH
        {
            let symbolcost: c_double = costfn(ZOPFLI_MAX_MATCH as c_uint, 1 as c_uint, costcontext);
            // SAFETY: j is within block, so costs[j] is valid.
            let base_cost = unsafe { *costs.add(j) as c_double };
            let fill_cost = (base_cost + symbolcost) as c_float;
            let target = j.wrapping_add(max_match_usize);

            // SAFETY: target is within 0..=blocksize as in original logic.
            unsafe {
                *costs.add(target) = fill_cost;
                *length_array.add(target) = max_match_ushort;
            }

            let mut k = 0usize;
            while k < max_match_usize {
                i = i.wrapping_add(1);
                j = j.wrapping_add(1);
                ZopfliUpdateHash(in_0, i, inend, h);
                // SAFETY: target remains within initialized DP arrays during this fast-forward path.
                unsafe {
                    *costs.add(j.wrapping_add(max_match_usize)) = fill_cost;
                    *length_array.add(j.wrapping_add(max_match_usize)) = max_match_ushort;
                }
                k = k.wrapping_add(1);
            }
        }

        let mut dist: c_ushort = 0;
        let mut leng: c_ushort = 0;
        ZopfliFindLongestMatch(
            s,
            h,
            in_0,
            i,
            inend,
            max_match_usize,
            &raw mut sublen as *mut c_ushort,
            &raw mut dist,
            &raw mut leng,
        );

        // SAFETY: j is within block, so costs[j] is valid.
        let cost_j = unsafe { *costs.add(j) as c_double };

        if i.wrapping_add(1) <= inend {
            let new_cost: c_double =
                costfn(
                    // SAFETY: i < inend in loop condition, so input byte is valid.
                    unsafe { *in_0.add(i) as c_uint },
                    0 as c_uint,
                    costcontext,
                ) + cost_j;
            let next = j.wrapping_add(1);
            // SAFETY: next is within 1..=blocksize.
            unsafe {
                if new_cost < *costs.add(next) as c_double {
                    *costs.add(next) = new_cost as c_float;
                    *length_array.add(next) = 1 as c_ushort;
                }
            }
        }

        let kend = zopfli_min(leng as size_t, inend.wrapping_sub(i));
        let mincostaddcostj: c_double = mincost + cost_j;
        let mut k = 3usize;
        while k <= kend {
            let idx = j.wrapping_add(k);
            // SAFETY: idx is within DP array bounds by construction.
            let old_cost = unsafe { *costs.add(idx) as c_double };
            if !(old_cost <= mincostaddcostj) {
                let new_cost =
                    costfn(k as c_uint, sublen[k as usize] as c_uint, costcontext) + cost_j;
                if new_cost < old_cost {
                    // SAFETY: idx is within DP array bounds by construction.
                    unsafe {
                        *costs.add(idx) = new_cost as c_float;
                        *length_array.add(idx) = k as c_ushort;
                    }
                }
            }
            k = k.wrapping_add(1);
        }

        i = i.wrapping_add(1);
    }

    // SAFETY: blocksize is within the allocated DP arrays.
    unsafe { *costs.add(blocksize) as c_double }
}

